import type { System } from '../../Engine/System';
import type { World } from '../../Engine/World';
import type { Plane } from '../Entity/Plane';
import { BATTLE_EVENT } from '../BattleEvents';
import type { CardConfigData, CardEffectType } from '../Config/CardConfig';

export class CardApplySystem implements System {

    private _world: World = null!;

    onStart(world: World): void {
        this._world = world;
        world.bus.on(BATTLE_EVENT.CARD_SELECTED, this._onCardSelected, this);
    }

    onDestroy(world: World): void {
        world.bus.off(BATTLE_EVENT.CARD_SELECTED, this._onCardSelected, this);
        this._world = null!;
    }

    onTick(_world: World, _dt: number): void {
        // 事件驱动
    }

    private _onCardSelected(card: CardConfigData): void {
        const player = this._findPlayer();
        if (!player) return;

        // 1. 生效
        for (const effect of card.effects) {
            this._applyEffect(player, effect.type, effect.value);
        }

        // 2. 记叠层
        const stacks = player.cardStacks.get(card.id) ?? 0;
        player.cardStacks.set(card.id, stacks + 1);

        console.log(`[CardApplySystem] ${card.name} 生效，叠了 ${stacks + 1} 层`);
    }

    private _applyEffect(player: Plane, type: CardEffectType, value: number): void {
        switch (type) {
            case 'bullet_count': {
                const w = player.weapons[0];
                if (w) {
                    w.config.spreadCount = (w.config.spreadCount ?? 1) + value;
                    if ((w.config.spreadAngle ?? 0) <= 0) {
                        w.config.spreadAngle = 20;
                    }
                }
                break;
            }
            case 'bullet_damage': {
                const w = player.weapons[0];
                if (w) w.config.bulletDamage *= value;
                break;
            }
            case 'fire_rate': {
                const w = player.weapons[0];
                if (w) w.config.fireInterval *= value;
                break;
            }
            case 'move_speed': {
                const w = player.weapons[0];
                if (w) w.config.bulletSpeed *= value;
                break;
            }
            case 'max_hp':
                player.maxHp += value;
                break;
            case 'heal':
                player.hp = Math.min(player.hp + value, player.maxHp);
                break;
        }
    }

    private _findPlayer(): Plane | null {
        for (const p of this._world.query<Plane>('player')) return p;
        return null;
    }
}